 CheckBox CreatorOption(FlowLayoutPanel parent,string text,bool value){var c=new CheckBox{Text=text,Checked=value,AutoSize=true,MaximumSize=new Size(440,0),Margin=new Padding(0,8,0,3)};parent.Controls.Add(c);creatorInputs.Add(c);return c;}
 void AddCreatorVideos(IEnumerable<string> paths){if(busy)return;foreach(string path in paths){if(creatorProjects.Count>=500)break;string full=Path.GetFullPath(path);if(!File.Exists(full)||creatorProjects.Any(p=>p.Video.Equals(full,StringComparison.OrdinalIgnoreCase)))continue;creatorProjects.Add(CreatorProject.FromVideo(full));}SaveCreator();RefreshCreatorRows();tabs.SelectedTab=creatorPage;}
 void FitCreatorReview(){if(creatorFitting||creatorCues==null||creatorCues.Columns.Count<5)return;creatorFitting=true;try{float scale=beoAppearance==null?1:beoAppearance.Scale/100f;creatorCues.Columns["start"].Width=creatorCues.Columns["end"].Width=(int)(110*scale);foreach(DataGridViewRow row in creatorCues.Rows){int h=(int)(56*scale);foreach(string name in new[]{"en","vi"}){var cell=row.Cells[name];int w=Math.Max(40,cell.OwningColumn.Width-18);h=Math.Max(h,TextRenderer.MeasureText(Convert.ToString(cell.Value),creatorCues.Font,new Size(w,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl|TextFormatFlags.NoPrefix).Height+18);}row.Height=Math.Max(row.MinimumHeight,h);}}finally{creatorFitting=false;}}
 string CreatorStateLabel(string state){switch(state){case "QUEUED":return "Chờ xuất";case "RUNNING":return "Đang xử lý";case "PACKAGE_EXPORTED":return "Đã xuất gói dựng";case "MP4_EXPORTED":return "Đã xuất MP4";case "NEEDS_REVIEW":return "Cần xử lý đầu vào";case "TRANSLATION_INCOMPLETE":return "Thiếu bản dịch Việt";case "EXPORT_FAILED":return "Lỗi xuất gói";case "CANCELLED":return "Đã dừng";case "INTERRUPTED":return "Gián đoạn · có thể chạy lại";default:return state;}}
 void RefreshCreatorRows(){if(creatorGrid==null)return;var current=CreatorCurrent;bool rebuilt=false;creatorUpdating=true;try{if(creatorGrid.Rows.Count!=creatorProjects.Count||creatorGrid.Rows.Cast<DataGridViewRow>().Where((r,i)=>r.Tag!=creatorProjects[i]).Any()){rebuilt=true;creatorGrid.Rows.Clear();foreach(var p in creatorProjects){int i=creatorGrid.Rows.Add(p.Selected,p.Name+"\r\n"+CreatorStateLabel(p.State),p.Progress.Read().Percent,p.State=="RUNNING"?p.Progress.Read().Eta:"—");creatorGrid.Rows[i].Tag=p;}if(current!=null){int i=creatorProjects.IndexOf(current);if(i>=0)creatorGrid.CurrentCell=creatorGrid.Rows[i].Cells[1];}}
   else foreach(DataGridViewRow row in creatorGrid.Rows){var p=(CreatorProject)row.Tag;row.Cells[0].Value=p.Selected;row.Cells[1].Value=p.Name+"\r\n"+CreatorStateLabel(p.State);row.Cells[2].Value=p.Progress.Read().Percent;row.Cells[3].Value=p.State=="RUNNING"?p.Progress.Read().Eta:p.State.EndsWith("EXPORTED")?"Đã xuất":"—";row.Cells[1].ToolTipText=p.Error;row.DefaultCellStyle.BackColor=p.State=="NEEDS_REVIEW"||p.State=="TRANSLATION_INCOMPLETE"?CurrentBeoPalette.Warning:p.State=="EXPORT_FAILED"?CurrentBeoPalette.Error:CurrentBeoPalette.Surface;}
   creatorRun.Enabled=!busy&&creatorProjects.Any(p=>p.Selected);creatorCheck.Enabled=!busy&&CreatorCurrent!=null;
  }finally{creatorUpdating=false;}if(rebuilt)LoadCreatorDetail();}
 void LoadCreatorDetail(){if(creatorUpdating||creatorPaths==null)return;creatorUpdating=true;try{var p=CreatorCurrent;creatorTitle.Text=p==null?"Chọn clip để kiểm tra":p.Name;creatorPaths.Text=p==null?"":"Video: "+p.Video+"\r\nWAV: "+p.Voice+"\r\nSRT cuối: "+p.FinalSrt+"\r\nXuất: "+p.OutputFolder;if(p==null){creatorCues.Rows.Clear();creatorCaption.Text="";creatorAuditText.Text="Thêm/chọn clip để kiểm tra.";return;}creatorKind.SelectedIndex=p.ExportMp4?1:0;creatorVi.Checked=p.RequireVietnamese;creatorReviewed.Checked=p.UserReviewed;creatorBurn.Checked=p.BurnCaptions;creatorVertical.Checked=p.Vertical;creatorMix.Checked=p.MixOriginal;creatorGain.Value=(decimal)(p.OriginalGain*100);creatorCaption.Text=p.Caption;creatorCues.Rows.Clear();if(File.Exists(p.FinalSrt))try{var cues=Scripts.ParseSrt(File.ReadAllText(p.FinalSrt));bool vi=CreatorPipeline.TranslationReady(p,cues);foreach(var c in cues)creatorCues.Rows.Add(c.Id,Scripts.Stamp(c.Start),Scripts.Stamp(c.End),c.Text,vi?p.Translation.Text[c.Id]:"Chưa có bản dịch khớp SRT này");FitCreatorReview();}catch(Exception ex){creatorAuditText.Text=ex.Message;}if(p.Error.Length>0)creatorAuditText.Text=p.Error;
   CreatorAudit audit;if(p.Error.Length>0)creatorAuditText.Text=p.Error;else if(creatorAudits.TryGetValue(p.Id,out audit))creatorAuditText.Text=audit.Summary();else creatorAuditText.Text="Bấm Kiểm tra clip để đo dữ liệu hiện tại.\r\nTrạng thái dự án: "+p.State;
  }finally{creatorUpdating=false;}}
 void CreatorOptionsChanged(){if(creatorUpdating||busy)return;var p=CreatorCurrent;if(p==null)return;p.ExportMp4=creatorKind.SelectedIndex==1;p.RequireVietnamese=creatorVi.Checked;if(creatorReviewed.Checked&&!p.UserReviewed)try{p.AcknowledgePair(()=>false);}catch(Exception ex){status.Text="Chưa xác nhận cặp file: "+ex.Message;creatorUpdating=true;creatorReviewed.Checked=false;creatorUpdating=false;}p.UserReviewed=creatorReviewed.Checked;if(!p.UserReviewed)p.ReviewedPairKey="";p.BurnCaptions=creatorBurn.Checked;p.Vertical=creatorVertical.Checked;p.MixOriginal=creatorMix.Checked;p.OriginalGain=(double)creatorGain.Value/100;p.Caption=creatorCaption.Text;p.State="QUEUED";p.Progress.Restore(0,0,false);creatorAudits.Remove(p.Id);SaveCreator();creatorPaths.Text="Video: "+p.Video+"\r\nWAV: "+p.Voice+"\r\nSRT cuối: "+p.FinalSrt+"\r\nXuất: "+p.OutputFolder;}
 void AttachCreator(string what){var p=CreatorCurrent;if(busy||p==null)return;using(var d=new OpenFileDialog{Filter=what=="voice"?"Voice PCM mono 24kHz/16-bit|*.wav":"SRT|*.srt"})if(d.ShowDialog()==DialogResult.OK){if(what=="voice")p.Voice=d.FileName;else if(what=="source")p.SourceSrt=d.FileName;else{p.FinalSrt=d.FileName;p.Translation=null;}p.UserReviewed=false;p.State="QUEUED";p.Progress.Restore(0,0,false);SaveCreator();RefreshCreatorRows();LoadCreatorDetail();}}
 void UseCreatorVoice(){var p=CreatorCurrent;if(p==null||busy)return;var j=jobGrid.CurrentRow==null?null:jobs.ElementAtOrDefault(jobGrid.CurrentRow.Index);string wave=j!=null&&File.Exists(j.OutputPath)?j.OutputPath:lastOutput;if(!File.Exists(wave)){status.Text="Chưa có WAV hoàn tất; chạy ở Hàng đợi/Tạo voice trước.";return;}string srt=Path.Combine(Path.GetDirectoryName(wave),Path.GetFileNameWithoutExtension(wave)+".final.srt");if(!File.Exists(srt)){status.Text="Kết quả này thiếu final.srt.";return;}p.Voice=wave;p.FinalSrt=srt;p.UserReviewed=false;p.Translation=null;p.State="QUEUED";p.Progress.Restore(0,0,false);SaveCreator();RefreshCreatorRows();LoadCreatorDetail();}
 void SetCreatorBusy(bool value){foreach(Control c in creatorInputs)c.Enabled=!value;}
 async Task CheckCreator(){var p=CreatorCurrent;if(busy||p==null)return;creatorCancelled=false;SetBusy(true);try{var audit=await Task.Run(()=>CreatorPipeline.Inspect(root,p,()=>creatorCancelled));creatorAudits[p.Id]=audit;creatorAuditText.Text=audit.Summary();creatorDetailTabs.SelectedIndex=0;status.Text=audit.CanExport?"Đã kiểm tra đầu vào · xem cảnh báo và tùy chọn dịch.":"Clip cần xử lý · xem các dòng ERROR.";}catch(OperationCanceledException){status.Text="Đã dừng kiểm tra clip.";}catch(Exception ex){creatorAuditText.Text=ex.ToString();status.Text=ex.Message;}finally{SetBusy(false);}}
 async Task ImportCreatorTools(){if(busy)return;using(var d=new OpenFileDialog{Filter="FFmpeg Windows static|ffmpeg.exe",Title="Chọn FFmpeg Windows static đầy đủ (từ nguồn tin cậy)"}){if(d.ShowDialog()!=DialogResult.OK)return;string file=d.FileName;creatorCancelled=false;SetBusy(true);try{await Task.Run(()=>CreatorMedia.Import(root,file,()=>creatorCancelled));status.Text="Đã kiểm tra và nhập thành phần video riêng; bộ audio giữ nguyên.";}catch(Exception ex){status.Text=ex.Message;}finally{SetBusy(false);}}}
 async Task RunCreator(){if(busy)return;var selected=creatorProjects.Where(p=>p.Selected).ToList();if(selected.Count==0)return;creatorCancelled=false;SetBusy(true);int done=0,failed=0;
  try{var translator=new LocalAi(root,SelectedDevice());await Task.Run(()=>{foreach(var p in selected){if(creatorCancelled)break;p.Progress.Begin();int savedPercent=-5;try{var audit=CreatorPipeline.Export(root,p,Path.Combine(stateDir,"translation-cache"),translator,()=>creatorCancelled,(n,m)=>{p.Progress.Update(n,m);if(n<100&&n>=savedPercent+5){WriteCreator();savedPercent=n;}if(IsHandleCreated&&!IsDisposed)BeginInvoke((Action)(()=>{status.Text=p.Name+" · "+m;RefreshCreatorRows();}));},WriteCreator);p.Progress.Finish(true);done++;if(IsHandleCreated&&!IsDisposed)BeginInvoke((Action)(()=>{creatorAudits[p.Id]=audit;if(CreatorCurrent==p){creatorAuditText.Text=audit.Summary();LoadCreatorDetail();}}));}
    catch(OperationCanceledException){p.Progress.Finish(false);SaveCreator();break;}catch(Exception){p.Progress.Finish(false);failed++;}finally{SaveCreator();}}});
   status.Text=(creatorCancelled?"Đã dừng":"Đã kết thúc")+" Creator · "+done+" gói xuất/dùng lại · "+failed+" clip cần xử lý. Các clip khác tiếp tục độc lập.";
  }finally{SetBusy(false);RefreshCreatorRows();LoadCreatorDetail();SaveCreator();}}
}
}
